    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Penalize creating "dead space" (residuals too small for future items)
    // If post_residual is between 1 and 9, it is highly likely to be wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // 2. Lookahead optimization: If the next item fits into the post_residual, 
    // reward this placement significantly to encourage packing pairs.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0 * (1.0 - (next_item_size as f64 / 100.0));
    }

    // 3. Dynamic Thresholding: As we approach the end of the stream, 
    // become more aggressive in packing to minimize the number of open bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 * progress;
    }

    // 4. Global State Balancing: Avoid piling items into bins that are already 
    // significantly fuller than the current mean residual of all open bins.
    if (bin_capacity - bin_residual) as f64 > mean_residual {
        score += 15.0;
    }

    // 5. New bin penalty: Make it expensive to open a new bin unless the 
    // current fit is truly terrible (high post_residual).
