pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the residual space; we want to minimize this (Best Fit principle).
    let mut score = post;

    // Penalty for creating a "fragmented" bin: if post_residual is small but not zero,
    // it is often harder to fill later. We penalize values in the (0, 15] range.
    if post > 0.0 && post < 15.0 {
        score += (15.0 - post) * 2.5;
    }

    // Lookahead logic: if the next item is large, favor bins that can accommodate it.
    // If post_residual is smaller than next_item_size, we penalize the current choice
    // because it might strand the next item.
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            score += (next_item_size as f64 - post) * 1.5;
        }
    }

    // Dynamic thresholding: as the stream progresses, be more conservative about 
    // opening new bins. If fitting_bins_count is low, prioritize filling existing bins.
    if bin_residual == bin_capacity {
        // This is the "New Bin" candidate.
        // We increase the cost of opening a new bin as we progress through the stream,
        // unless the mean_residual is very high (indicating many wasted empty spaces).
        score += 40.0 + (progress * 30.0) - (mean_residual * 0.2);
    } else {
        // Existing bin: reward fitting the item if it leaves little residual space.
        // The weight of this preference increases slightly over time.
        score -= (1.0 - progress) * (bin_capacity as f64 - post) * 0.1;

        // If this is the only bin that fits, prioritize it strongly.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    score
