    let mut score = post_residual as f64;

    if is_new_bin {
        // Dynamic new-bin suppression. As the stream progresses, the cost to open a new bin 
        // increases proportionally to the number of open bins and the average residual, 
        // effectively forcing the algorithm to pack into existing bins until they are too fragmented.
        let dynamic_penalty = (open_bins_count as f64 * 48.0) * (1.2 + progress.powi(2)) + (mean_residual * 2.5);
        score += dynamic_penalty;
    } else {
        // Dead zone refinement: Small residuals (1-24) are often traps.
        // We penalize them proportionally so that larger residuals (closer to fitting nothing) 
        // are preferred over tiny, unusable gaps.
        if post_residual > 0 && post_residual < 25 {
            score += 110.0 - (post_residual as f64 * 1.5);
        }

        // Lookahead Synergy: Heavily reward placing items into gaps that perfectly match 
        // the next item size to reduce fragmentation cascades.
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                score -= 85.0;
                if post_residual == next_item_size {
                    score -= 75.0; 
                }
            } else {
                // Penalize blocking the next item as a function of remaining stream length.
                score += 55.0 * (1.0 - progress);
            }
        }

        // Criticality: If this is the only bin capable of holding the item, 
        // it must be selected to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 200.0;
        }

        // Adaptive Compaction: Shift residual distribution toward the mean. 
        // Over-filled bins (low residual) are rewarded, under-filled bins are penalized.
        let residual_diff = post_residual as f64 - mean_residual;
        if residual_diff < 0.0 {
            score -= 55.0 * fill_ratio;
        } else {
            score += residual_diff * 0.85;
        }

        // Density Floor: Aggressively discourage bins that are under-utilized.
        if fill_ratio < 0.65 {
            score += 60.0 * (0.65 - fill_ratio);
        }
    }

    score
}
